import json,re,time
from pathlib import Path
import serial
PORT='/dev/cu.usbserial-130'; BAUD=115200
PEN_UP=6.12; PEN_DOWN=2.97; ZF=180; TF=3000; DF=1200
report=json.loads(Path('samples/gcode/shaft-50x20-showcase.report.json').read_text())
if not report.get('safety',{}).get('valid'): raise RuntimeError('report safety invalid')
if report['safety'].get('homing_present') or report['safety'].get('heater_commands_present') or report['safety'].get('extrusion_present'): raise RuntimeError('report contains forbidden behavior')
b=report['bounds_mm']
if not (8.0 <= b['min_x'] <= b['max_x'] <= 218.0 and 41.0 <= b['min_y'] <= b['max_y'] <= 225.0): raise RuntimeError(f'bounds outside normal envelope: {b}')
raw=Path('samples/gcode/shaft-50x20-showcase.gcode').read_text().splitlines()
commands=[]
allowed={'G90','G0','G1','M400'}
for n,line in enumerate(raw,1):
    cmd=line.split(';',1)[0].strip()
    if not cmd: continue
    op=cmd.split()[0]
    if op not in allowed: raise RuntimeError(f'forbidden op line {n}: {cmd}')
    if op=='G28' or op in {'M104','M109','M140','M190'} or re.search(r'(^|\s)E[-+0-9.]',cmd): raise RuntimeError(f'unsafe line {n}: {cmd}')
    vals={}
    for tok in cmd.split()[1:]:
        if tok[0] in 'XYZF' and len(tok)>1: vals[tok[0]]=float(tok[1:])
    if 'X' in vals and not 8.0 <= vals['X'] <= 218.0: raise RuntimeError(f'X out of bounds line {n}: {cmd}')
    if 'Y' in vals and not 41.0 <= vals['Y'] <= 225.0: raise RuntimeError(f'Y out of bounds line {n}: {cmd}')
    if 'Z' in vals and vals['Z'] not in {PEN_UP,PEN_DOWN}: raise RuntimeError(f'Z not calibrated line {n}: {cmd}')
    commands.append(cmd)
if commands[:3] != ['G90',f'G0 Z{PEN_UP:.2f} F{ZF}','G0 X38.00 Y208.00 F3000']:
    raise RuntimeError(f'unexpected artwork preamble: {commands[:3]}')
if commands[-2:] != [f'G0 Z{PEN_UP:.2f} F{ZF}','M400']: raise RuntimeError(f'unexpected artwork ending: {commands[-2:]}')
print(f'PREFLIGHT_OK commands={len(commands)} bounds={b}',flush=True)
def read_until_ok(ser,sent,timeout):
    deadline=time.monotonic()+timeout; seen=[]
    while time.monotonic()<deadline:
        raw=ser.readline()
        if not raw: continue
        text=raw.decode('utf-8',errors='replace').strip()
        if not text: continue
        seen.append(text)
        low=text.lower()
        if low.startswith('error') or 'printer halted' in low or 'kill() called' in low: raise RuntimeError(f'printer error after {sent!r}: {text}')
        if low.startswith('resend') or low.startswith('rs '): raise RuntimeError(f'resend after {sent!r}: {text}')
        if low=='ok' or low.startswith('ok '): return seen
    raise TimeoutError(f'timeout after {sent!r}; rx={seen[-8:]}')
def send(ser,cmd,timeout=30):
    ser.write((cmd+'\n').encode('ascii')); ser.flush(); return read_until_ok(ser,cmd,timeout)
with serial.Serial(PORT,BAUD,timeout=0.25,write_timeout=2) as ser:
    time.sleep(2.0); ser.reset_input_buffer()
    ident=send(ser,'M115',20)
    ident_text=' | '.join(ident)
    if 'FIRMWARE_NAME:' not in ident_text.upper() or 'ANYCUBICKOBRA' not in ident_text.upper(): raise RuntimeError(f'M115 did not identify Anycubic Kobra: {ident_text}')
    print('PRINTER_IDENTIFIED '+ident_text,flush=True)
    send(ser,'G28 X Y',120); print('HOMING_XY_OK',flush=True)
    send(ser,'G28 Z',120); print('HOMING_Z_OK',flush=True)
    send(ser,'G90'); send(ser,f'G0 Z{PEN_UP:.2f} F{ZF}'); print('PEN_UP_OK',flush=True)
    total=len(commands)
    for idx,cmd in enumerate(commands,1):
        send(ser,cmd,300 if cmd=='M400' else 30)
        if idx==5: print('DRAWING_STARTED first_draw_move=G1_X188.00_Y208.00',flush=True)
        if idx%100==0 or idx==total: print(f'PROGRESS {idx}/{total}',flush=True)
    send(ser,f'G0 Z{PEN_UP:.2f} F{ZF}'); send(ser,'M400',300)
print('RESULT:SHAFT50_SHOWCASE_COMPLETE_PEN_UP',flush=True)
